from pathlib import Path
import json,numpy as np
from scipy.interpolate import PchipInterpolator
W=Path(__file__).resolve().parent;p=json.loads((W/'correction_plan.json').read_text());a=np.array(p['front_lateral_path_m']);curve=PchipInterpolator(a[:,0],a[:,1]);derivative=curve.derivative();x=np.linspace(0,p['downward_stroke_m'],1001);d=np.array(p['bodyward_direction_sim']);out=dict(scope='Corrected trajectory geometry controls only',finite=bool(np.isfinite(curve(x)).all() and np.isfinite(derivative(x)).all()),first_x_shift_m=float(curve(0)),last_x_shift_m=float(curve(x[-1])),max_lateral_slope=float(np.max(abs(derivative(x)))),peak_downward_speed_m_s=1.875*p['downward_stroke_m']/p['durations_s'][0],horizontal_height_change_m=float(d[1]*p['horizontal_withdrawal_m']),slide_height_change_m=float(np.array(p['blade_slide_direction_sim'])[1]*p['blade_slide_distance_m']));out['passed']=bool(out['finite'] and abs(out['first_x_shift_m'])<1e-12 and abs(out['horizontal_height_change_m'])<1e-12 and abs(out['slide_height_change_m'])<1e-12 and abs(out['peak_downward_speed_m_s']-.09375)<1e-12);(W/'motion_controls_result.json').write_text(json.dumps(out,indent=2));print(json.dumps(out,indent=2))
